class PieceType(Enum):
    """Chess piece types."""
    KING   = "king"
    QUEEN  = "queen"
    BISHOP = "bishop"
    KNIGHT = "knight"
    ROOK   = "rook"
    PAWN   = "pawn"

    @property
    def icon(self):
        return {"king": "♚", "queen": "♛", "bishop": "♝",
                "knight": "♞", "rook": "♜", "pawn": "♟"}[self.value]


